import fs from 'node:fs';
import path from 'node:path';
import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';

function expandInstancedMeshes(root) {
  const targets = [];
  root.traverse((child) => {
    if (child.isInstancedMesh) {
      targets.push(child);
    }
  });

  for (const instanced of targets) {
    const parent = instanced.parent;
    if (!parent) continue;

    const group = new THREE.Group();
    group.name = instanced.name || 'instanced_group';

    const tempMatrix = new THREE.Matrix4();

    for (let i = 0; i < instanced.count; i += 1) {
      instanced.getMatrixAt(i, tempMatrix);
      const mesh = new THREE.Mesh(instanced.geometry, instanced.material);
      mesh.name = `${instanced.name || 'instance'}_${i}`;
      mesh.applyMatrix4(tempMatrix);
      group.add(mesh);
    }

    group.position.copy(instanced.position);
    group.quaternion.copy(instanced.quaternion);
    group.scale.copy(instanced.scale);
    group.updateMatrix();

    parent.add(group);
    parent.remove(instanced);
  }
}

const root = createScene();

// Convert instanced meshes to regular meshes for OBJ export.
expandInstancedMeshes(root);

// Apply Y-up -> Z-up conversion for Blender.
root.rotation.x = -Math.PI / 2;
root.updateMatrixWorld(true);

const exporter = new OBJExporter();
const objText = exporter.parse(root);

const outPath = '/root/output/object.obj';
fs.mkdirSync(path.dirname(outPath), { recursive: true });
fs.writeFileSync(outPath, objText, 'utf8');

console.log(`Wrote ${outPath}`);
